define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_23.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e146301","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_22.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e146405","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_17.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e146509","topics":[]},{"title":"Installing the hoist","shortdesc":"<p class=\"shortdesc\">Install the hoist in order to replace components within the Integrated System Cabinet (ISC) and Integrated Cooling Cabinet (ICC).<\/p>","href":"t_InstallingTheHoist_3.html","attributes":{"data-id":"id_2003492"},"menu":{"hasChildren":false},"tocID":"id_2003492-d46e146613","topics":[]},{"title":"Removing the Cabinet Cooling Unit (CCU)","shortdesc":"<p class=\"shortdesc\">Remove the CCU form the Integrated Cooling Cabinet (ICC)<\/p>","href":"t_RemovingTheCCU.html","attributes":{"data-id":"id_2001577"},"menu":{"hasChildren":false},"tocID":"id_2001577-d46e146717","topics":[]},{"title":"Installing the Cabinet Cooling Unit (CCU)","shortdesc":"<p class=\"shortdesc\">Installing the CCU in the Integrated Cooling Cabinet (ICC).<\/p>","href":"t_InstallingTheCCU.html","attributes":{"data-id":"id_2002032"},"menu":{"hasChildren":false},"tocID":"id_2002032-d46e146821","topics":[]},{"title":"Refilling the Integrated Cooling Cabinet (ICC) coolant","shortdesc":"<p class=\"shortdesc\">Fill the Cabinet Cooling Unit (CCU) and Gradient Cooling Unit (GCU) tanks with coolant, as needed.<\/p>","href":"t_RefillingCoolant_3.html","attributes":{"data-id":"id_2002771"},"menu":{"hasChildren":false},"tocID":"id_2002771-d46e146925","topics":[]},{"title":"Removing the hoist","shortdesc":"<p class=\"shortdesc\">Remove the hoist beam and return it to its storage location.<\/p>","href":"t_RemovingTheHoist_3.html","attributes":{"data-id":"id_2003868"},"menu":{"hasChildren":false},"tocID":"id_2003868-d46e147029","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_19.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e147133","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_22.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e147237","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_40.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e147343","topics":[]}]});